using Mono.Cecil;using Mono.Cecil.Cil;
foreach(string mode in new[]{"rename","body-mutated","wrong-name"}){using var module=ModuleDefinition.ReadModule(args[0]);var type=module.Types.Single(t=>t.FullName=="HideIt.ModManager");var method=type.Methods.Single(m=>m.Name=="Update");method.Name=mode=="wrong-name"?"UnknownUpdate":"FpsBoosterUpdate";if(mode=="body-mutated")method.Body.Instructions.Insert(0,Instruction.Create(OpCodes.Nop));module.Write(Path.Combine(args[1],mode+".dll"));}using(var module=ModuleDefinition.ReadModule(args[2])){module.Types.First(t=>t.Name!="<Module>").Name+="Unreviewed";module.Write(Path.Combine(args[1],"bad-updater.dll"));}
